 * Renders a parsed document tree (see parser.js) as either indented JSON or
 * the `keys` listing.
 */
import { codePointCompare } from './path.js'

function sortedKeys(table) {
  return Array.from(table.entries.keys()).sort(codePointCompare)
}

function jsonString(s) {
  let out = '"'
  for (const ch of s) {
    if (ch === '"') out += '\\"'
    else if (ch === '\\') out += '\\\\'
    else if (ch === '\n') out += '\\n'
    else if (ch === '\t') out += '\\t'
    else if (ch === '\r') out += '\\r'
    else {
      const code = ch.codePointAt(0)
      if (code < 0x20) out += `\\u${code.toString(16).padStart(4, '0')}`
      else out += ch
    }
  }
  return out + '"'
}

function jsonArrayLike(items, indent) {
  if (items.length === 0) return '[]'
  const inner = indent + '  '
  const lines = items.map((item) => inner + jsonValue(item, inner))
  return `[\n${lines.join(',\n')}\n${indent}]`
}

function jsonValue(node, indent) {
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node)
      if (keys.length === 0) return '{}'
      const inner = indent + '  '
      const lines = keys.map((k) => `${inner}${jsonString(k)}: ${jsonValue(node.entries.get(k), inner)}`)
      return `{\n${lines.join(',\n')}\n${indent}}`
    }
    case 'aot':
      return jsonArrayLike(node.items, indent)
    case 'array':
      return jsonArrayLike(node.items, indent)
    case 'string':
      return jsonString(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    case 'integer':
      return node.value
    case 'float':
      return String(node.value)
    default:
      throw new Error(`unknown node kind ${node.kind}`)
  }
}

export function toJSON(root) {
  return `${jsonValue(root, '')}\n`
}

function typeOf(node) {
  if (node.kind === 'aot') return 'array'
  return node.kind
}

export function toKeys(root) {
  const lines = []
  function visit(node, path) {
    lines.push(`${path} ${typeOf(node)}\n`)
    if (node.kind === 'table') {
      for (const k of sortedKeys(node)) {
        visit(node.entries.get(k), path === '' ? k : `${path}.${k}`)
      }
    } else if (node.kind === 'aot' || node.kind === 'array') {
      node.items.forEach((item, idx) => visit(item, `${path}[${idx}]`))
    }
  }
  for (const k of sortedKeys(root)) visit(root.entries.get(k), k)
  return lines.join('')
}
"}

