{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-193jzP/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import { readFileSync } from 'node:fs'
import { parseDocument } from './parser.js'
import { toJSON, toKeys } from './format.js'
import { ParseError } from './errors.js'

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'json' && mode !== 'keys')) {
    process.stderr.write('error: usage: cli.js json|keys\n')
    process.exit(2)
  }

  const input = readFileSync(0, 'utf8')

  let root
  try {
    root = parseDocument(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  process.stdout.write(mode === 'json' ? toJSON(root) : toKeys(root))
  process.exit(0)
}

main()
"}

