{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-2ANskE/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { parseUri, normalize, resolve, UriError } from './uri.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  const mode = args.length === 1 ? args[0] : undefined
  if (mode !== 'normalize' && mode !== 'resolve') {
    fail('usage: cli.js normalize|resolve')
  }

  const input = readFileSync(0, 'utf8')
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const results = []
  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const line = lines[i]
    try {
      if (mode === 'normalize') {
        results.push(normalize(parseUri(line)))
      } else {
        const spaceIdx = line.indexOf(' ')
        if (spaceIdx === -1) {
          throw new UriError('expected a base and a reference')
        }
        const base = parseUri(line.slice(0, spaceIdx))
        const ref = parseUri(line.slice(spaceIdx + 1))
        if (base.scheme === undefined) {
          throw new UriError('the base has no scheme')
        }
        results.push(resolve(base, ref))
      }
    } catch (e) {
      if (e instanceof UriError) {
        fail(`line ${lineNumber}: ${e.message}`)
      }
      throw e
    }
  }

  const output = results.map((line) => line + '\n').join('')
  process.stdout.write(output)
  process.exit(0)
}

main()
"}

