        results.push(resolve(base, ref))
      }
    } catch (e) {
      if (e instanceof UriError) {
        fail(`line ${lineNumber}: ${e.message}`)
      }
      throw e
    }
  }

  const output = results.map((line) => line + '\n').join('')
  process.stdout.write(output)
  process.exit(0)
}

main()
"}

