{"file_path":"src/scanner.js","content":"import { LexError } from './lex-error.js'
import { computePositions } from './positions.js'
import { isDecDigit, isIdStart } from './char-classes.js'
import { scanNumber } from './scan-number.js'
import { scanString, scanRawString } from './scan-string.js'
import { scanIdentifier } from './scan-identifier.js'

const TWO_CHAR_PUNCT = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const ONE_CHAR_PUNCT = new Set(['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'])

/**
 * Scans the whole input into tokens, per the language's grammar. Throws
 * `LexError` at the first ill-formed construct; otherwise returns every
 * token in order.
 *
 * Each token is `{ kind, pos: { line, col }, body }`, where `body` is
 * already the text `tokens` mode prints: source text for every kind but
 * `string` and `rawstring`, whose body is their decoded value as a JSON
 * string.
 */
export function scan(text) {
  const chars = Array.from(text)
  const positions = computePositions(chars)
  const len = chars.length
  const tokens = []
  let i = 0

  while (i < len) {
    const c = chars[i]

    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      i++
      continue
    }

    if (c === '/' && i + 1 < len && chars[i + 1] === '/') {
      i += 2
      while (i < len && chars[i] !== '\n') i++
      continue
    }

    if (c === '/' && i + 1 < len && chars[i + 1] === '*') {
      const pos = positions[i]
      let depth = 1
      i += 2
      while (depth > 0) {
        if (i >= len) throw new LexError(pos, 'unterminated block comment')
        if (chars[i] === '/' && i + 1 < len && chars[i + 1] === '*') {
          depth++
          i += 2
        } else if (chars[i] === '*' && i + 1 < len && chars[i + 1] === '/') {
          depth--
          i += 2
        } else {
          i++
        }
      }
      continue
    }

    if (c === '"') {
      const t = scanString(chars, positions, i, len)
      tokens.push({ kind: 'string', pos: t.pos, body: JSON.stringify(t.value) })
      i = t.end
      continue
    }

    if (c === 'r' && i + 1 < len && chars[i + 1] === '"') {
      const t = scanRawString(chars, positions, i, len)
      tokens.push({ kind: 'rawstring', pos: t.pos, body: JSON.stringify(t.value) })
      i = t.end
      continue
    }

    if (isIdStart(c)) {
      const t = scanIdentifier(chars, positions, i, len)
      tokens.push({ kind: t.kind, pos: t.pos, body: t.text })
      i = t.end
      continue
    }

    if (isDecDigit(c)) {
      const t = scanNumber(chars, positions, i, len)
      tokens.push({ kind: 'number', pos: t.pos, body: t.text })
      i = t.end
      continue
    }

    const two = i + 1 < len ? c + chars[i + 1] : null
    if (two !== null && TWO_CHAR_PUNCT.has(two)) {
      tokens.push({ kind: 'punct', pos: positions[i], body: two })
      i += 2
      continue
    }

    if (ONE_CHAR_PUNCT.has(c)) {
      tokens.push({ kind: 'punct', pos: positions[i], body: c })
      i += 1
      continue
    }

    throw new LexError(positions[i], `unexpected character ${c}`)
  }

  return tokens
}
"}

