content.arguments:
{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { scan } from './scanner.js'
import { LexError } from './lex-error.js'

const KIND_ORDER = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'tokens' && mode !== 'stats') {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const text = readStdin()

  let tokens
  try {
    tokens = scan(text)
  } catch (err) {
    if (err instanceof LexError) {
      process.stderr.write(`error: ${err.pos.line}:${err.pos.col}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }

  let out
  if (mode === 'tokens') {
    out = tokens.map((t) => `${t.pos.line}:${t.pos.col} ${t.kind} ${t.body}\n`).join('')
  } else {
    const counts = Object.fromEntries(KIND_ORDER.map((k) => [k, 0]))
    for (const t of tokens) counts[t.kind]++
    out = KIND_ORDER.map((k) => `${k} ${counts[k]}\n`).join('') + `total ${tokens.length}\n`
  }
  process.stdout.write(out)
  process.exit(0)
}

main()
"}

