{"file_path":"src/uri.js","content":"/**
 * URI reference parsing, normalization and resolution per RFC 3986's
 * generic syntax (sections 3, 5.2.2 and 5.3/6.2.2), as scoped by the
 * task's written specification.
 */

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

/** Raised for a malformed percent-encoding in one component. */
export class UriError extends Error {}

function lowerAscii(str) {
  return str.replace(/[A-Z]/g, (c) => String.fromCharCode(c.charCodeAt(0) + 32))
}

function isHexDigit(c) {
  return c !== undefined && /[0-9a-fA-F]/.test(c)
}

function isUnreserved(ch) {
  return /[A-Za-z0-9\-._~]/.test(ch)
}

function checkPercent(str, component) {
  for (let i = 0; i < str.length; i++) {
    if (str[i] === '%' && !(isHexDigit(str[i + 1]) && isHexDigit(str[i + 2]))) {
      throw new UriError(`the ${component} has a truncated percent-encoding`)
    }
  }
}

function normalizePercent(str) {
  let out = ''
  for (let i = 0; i < str.length; i++) {
    if (str[i] === '%') {
      const h1 = str[i + 1].toUpperCase()
      const h2 = str[i + 2].toUpperCase()
      const ch = String.fromCharCode(parseInt(h1 + h2, 16))
      out += isUnreserved(ch) ? ch : `%${h1}${h2}`
      i += 2
    } else {
      out += str[i]
    }
  }
  return out
}

function parseAuthority(authStr) {
  let userinfo = null
  let rest = authStr
  const lastAt = authStr.lastIndexOf('@')
  if (lastAt !== -1) {
    userinfo = authStr.slice(0, lastAt)
    rest = authStr.slice(lastAt + 1)
  }
  const lastBracket = rest.lastIndexOf(']')
  const colonIdx = rest.indexOf(':', lastBracket + 1)
  if (colonIdx !== -1) {
    return { userinfo, host: rest.slice(0, colonIdx), port: rest.slice(colonIdx + 1) }
  }
  return { userinfo, host: rest, port: null }
}

/**
 * Parse a URI reference into { scheme, authority, path, query, fragment }.
 * Absent components are null; `authority` is null or
 * { userinfo, host, port } where userinfo/port are null when absent.
 */
export function parseUriReference(input) {
  let s = input
  let scheme = null
  const firstColon = s.indexOf(':')
  if (firstColon !== -1 && !/[/?#]/.test(s.slice(0, firstColon))) {
    scheme = s.slice(0, firstColon)
    s = s.slice(firstColon + 1)
  }

  let authority = null
  if (s.startsWith('//')) {
    s = s.slice(2)
    const m = s.match(/[/?#]/)
    const end = m ? m.index : s.length
    authority = parseAuthority(s.slice(0, end))
    s = s.slice(end)
  }

  const pm = s.match(/[?#]/)
  const pathEnd = pm ? pm.index : s.length
  const path = s.slice(0, pathEnd)
  s = s.slice(pathEnd)

  let query = null
  if (s[0] === '?') {
    const hashIdx = s.indexOf('#')
    const end = hashIdx === -1 ? s.length : hashIdx
    query = s.slice(1, end)
    s = s.slice(end)
  }

  let fragment = null
  if (s[0] === '#') {
    fragment = s.slice(1)
  }

  return { scheme, authority, path, query, fragment }
}

/** Serialize a parsed URI reference back to text. */
export function serialize(u) {
  let out = ''
  if (u.scheme !== null) out += `${u.scheme}:`
  if (u.authority !== null) {
    out += '//'
    if (u.authority.userinfo !== null) out += `${u.authority.userinfo}@`
    out += u.authority.host
    if (u.authority.port !== null) out += `:${u.authority.port}`
  }
  out += u.path
  if (u.query !== null) out += `?${u.query}`
  if (u.fragment !== null) out += `#${u.fragment}`
  return out
}

/** Remove dot segments from a path per RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = `/${input.slice(3)}`
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = `/${input.slice(4)}`
      output = output.replace(/\/?[^/]*$/, '')
    } else if (input === '/..') {
      input = '/'
      output = output.replace(/\/?[^/]*$/, '')
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const m = input.match(/^\/?[^/]*/)
      output += m[0]
      input = input.slice(m[0].length)
    }
  }
  return output
}

function validatePercent(u) {
  checkPercent(u.path, 'path')
  if (u.authority !== null) {
    if (u.authority.userinfo !== null) checkPercent(u.authority.userinfo, 'userinfo')
    checkPercent(u.authority.host, 'host')
  }
  if (u.query !== null) checkPercent(u.query, 'query')
  if (u.fragment !== null) checkPercent(u.fragment, 'fragment')
}

/**
 * Normalize a parsed URI reference: lowercase the scheme, decode
 * percent-encoded unreserved characters, lowercase the host, drop a
 * default or empty port, remove dot segments, and root an empty path
 * when an authority is present. Throws UriError for a truncated
 * percent-encoding, checking path, userinfo, host, query and fragment
 * in that order.
 */
export function normalize(uRef) {
  validatePercent(uRef)

  const out = {
    scheme: uRef.scheme,
    authority: uRef.authority ? { ...uRef.authority } : null,
    path: uRef.path,
    query: uRef.query,
    fragment: uRef.fragment,
  }

  if (out.scheme !== null) out.scheme = lowerAscii(out.scheme)
  out.path = normalizePercent(out.path)
  if (out.query !== null) out.query = normalizePercent(out.query)
  if (out.fragment !== null) out.fragment = normalizePercent(out.fragment)

  if (out.authority !== null) {
    if (out.authority.userinfo !== null) out.authority.userinfo = normalizePercent(out.authority.userinfo)
    out.authority.host = lowerAscii(normalizePercent(out.authority.host))
    if (out.authority.port !== null) {
      const def = out.scheme !== null ? DEFAULT_PORTS[out.scheme] : undefined
      if (out.authority.port === '' || out.authority.port === def) out.authority.port = null
    }
  }

  out.path = removeDotSegments(out.path)
  if (out.authority !== null && out.path === '') out.path = '/'

  return out
}

function mergePaths(baseRef, refPath) {
  if (baseRef.authority !== null && baseRef.path === '') {
    return `/${refPath}`
  }
  const idx = baseRef.path.lastIndexOf('/')
  return idx === -1 ? refPath : baseRef.path.slice(0, idx + 1) + refPath
}

/**
 * Resolve a reference against a base per RFC 3986 section 5.2.2 in its
 * strict form (a reference that repeats the base's scheme is still an
 * absolute URI). The result is not normalized; call normalize() on it.
 */
export function resolveReference(baseRef, refRef) {
  const target = { fragment: refRef.fragment }

  if (refRef.scheme !== null) {
    target.scheme = refRef.scheme
    target.authority = refRef.authority
    target.path = removeDotSegments(refRef.path)
    target.query = refRef.query
  } else if (refRef.authority !== null) {
    target.scheme = baseRef.scheme
    target.authority = refRef.authority
    target.path = removeDotSegments(refRef.path)
    target.query = refRef.query
  } else if (refRef.path === '') {
    target.scheme = baseRef.scheme
    target.authority = baseRef.authority
    target.path = baseRef.path
    target.query = refRef.query !== null ? refRef.query : baseRef.query
  } else {
    target.scheme = baseRef.scheme
    target.authority = baseRef.authority
    target.path = refRef.path.startsWith('/')
      ? removeDotSegments(refRef.path)
      : removeDotSegments(mergePaths(baseRef, refRef.path))
    target.query = refRef.query
  }

  return target
}
"}

