{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { parseUriReference, serialize, normalize, resolveReference, UriError } from './uri.js'

/** Raised for a per-line usage problem, reported the same way as UriError. */
class LineError extends Error {}

function splitRecords(input) {
  if (input === '') return []
  const parts = input.split('\n')
  if (parts[parts.length - 1] === '') parts.pop()
  return parts
}

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.setEncoding('utf8')
    process.stdin.on('data', (c) => chunks.push(c))
    process.stdin.on('end', () => resolve(chunks.join('')))
    process.stdin.on('error', reject)
  })
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exitCode = 2
}

function processRecord(mode, record) {
  if (mode === 'normalize') {
    return serialize(normalize(parseUriReference(record)))
  }

  const spaceIdx = record.indexOf(' ')
  if (spaceIdx === -1) throw new LineError('expected a base and a reference')

  const base = parseUriReference(record.slice(0, spaceIdx))
  if (base.scheme === null) throw new LineError('the base has no scheme')

  const ref = parseUriReference(record.slice(spaceIdx + 1))
  return serialize(normalize(resolveReference(base, ref)))
}

async function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
    fail('usage: cli.js normalize|resolve')
    return
  }

  const records = splitRecords(await readStdin())
  const results = []

  for (let i = 0; i < records.length; i++) {
    try {
      results.push(processRecord(mode, records[i]))
    } catch (err) {
      if (err instanceof UriError || err instanceof LineError) {
        fail(`line ${i + 1}: ${err.message}`)
        return
      }
      throw err
    }
  }

  process.stdout.write(results.map((r) => `${r}\n`).join(''))
}

main()
"}

