{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-8021qO/src/sheet.js","content":"/**
 * Parses the sheet text format into a map from canonical cell address to
 * verbatim declared content.
 */

import { classifyAddress } from './address.js'

export class SheetError extends Error {
  constructor(message) {
    super(message)
  }
}

/**
 * Parses sheet text into a Map from canonical address (e.g. "A1") to the
 * cell's verbatim content. Throws SheetError with a ready-to-print message
 * (sans the "error: " prefix) on the first invalid or duplicate address.
 */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const stripped = lines[i].replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    const wsIndex = stripped.search(/[ \t]/)
    let addrPart, content
    if (wsIndex === -1) {
      addrPart = stripped
      content = ''
    } else {
      addrPart = stripped.slice(0, wsIndex)
      const after = stripped.slice(wsIndex)
      const skip = /^[ \t]+/.exec(after)[0].length
      content = after.slice(skip)
    }

    const addr = classifyAddress(addrPart)
    if (!addr) {
      throw new SheetError(`line ${lineNo}: invalid cell address ${addrPart}`)
    }
    if (cells.has(addr.key)) {
      throw new SheetError(`line ${lineNo}: cell ${addrPart} is declared twice`)
    }
    cells.set(addr.key, content)
  }

  return cells
}
"}

