 * Evaluates parsed cell content to a value, with per-cell memoization and
 * cycle detection shared across a whole sheet evaluation.
 */

import { parseFormula } from './parser.js'
import { keyFromColRow } from './address.js'
import { numVal, textVal, boolVal, errVal, toNumber, finiteNum, compareValues, ERROR_TOKENS } from './values.js'

const KNOWN_FUNCTIONS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

/** Parses a leaf (non-formula) cell's literal content into a value. */
export function evalLiteral(content) {
  if (content === '') return numVal(0)
  if (ERROR_TOKENS.includes(content)) return errVal(content)
  if (/^-?\d+(\.\d+)?$/.test(content)) return numVal(parseFloat(content))
  return textVal(content)
}

/** Creates an evaluator over a fixed set of declared cells (address -> raw
 * content). Values are cached across calls, so `values()` and repeated
 * `deps()` walks on the same instance reuse work and cycle state. */
export class SheetEvaluator {
  constructor(cells) {
    this.cells = cells
    this.cache = new Map()
    this.pending = new Set()
  }

  /** Evaluates the cell at the given canonical address, memoized. */
  evalAddress(key) {
    if (this.cache.has(key)) return this.cache.get(key)
    if (this.pending.has(key)) return errVal('#CYCLE!')
    this.pending.add(key)
    const content = this.cells.has(key) ? this.cells.get(key) : ''
    const value = this.evalContent(content)
    this.pending.delete(key)
    this.cache.set(key, value)
    return value
  }

  evalContent(content) {
    if (content.startsWith('=')) {
      const ast = parseFormula(content.slice(1))
      if (!ast) return errVal('#ERR!')
      return this.evaluate(ast)
    }
    return evalLiteral(content)
  }

  evaluate(node) {
    switch (node.type) {
      case 'num':
        return numVal(node.value)
      case 'bool':
        return boolVal(node.value)
      case 'addr':
        if (!node.valid) return errVal('#REF!')
        return this.evalAddress(node.key)
      case 'unary':
        return this.evalUnary(node)
      case 'binop':
        return this.evalBinop(node)
      case 'call':
        return this.evalCall(node)
      default:
        throw new Error(`unreachable node type ${node.type}`)
    }
  }

  evalUnary(node) {
    const v = this.evaluate(node.expr)
    const n = toNumber(v)
    if (n.t === 'err') return n
    return numVal(node.op === '-' ? -n.v : n.v)
  }

  evalBinop(node) {
    const left = this.evaluate(node.left)
    const right = this.evaluate(node.right)
    if (isComparisonOp(node.op)) {
      if (left.t === 'err') return left
      if (right.t === 'err') return right
      const cmp = compareValues(left, right)
      return boolVal(applyComparison(node.op, cmp))
    }
    const ln = toNumber(left)
    if (ln.t === 'err') return ln
    const rn = toNumber(right)
    if (rn.t === 'err') return rn
    return applyArith(node.op, ln.v, rn.v)
  }

  /** Evaluates a call argument to a list of values, expanding ranges. */
  evalArgToList(argNode) {
    if (argNode.type === 'range') {
      if (!argNode.from.valid || !argNode.to.valid) return [errVal('#REF!')]
      const minCol = Math.min(argNode.from.col, argNode.to.col)
      const maxCol = Math.max(argNode.from.col, argNode.to.col)
      const minRow = Math.min(argNode.from.row, argNode.to.row)
      const maxRow = Math.max(argNode.from.row, argNode.to.row)
      const values = []
      for (let c = minCol; c <= maxCol; c++) {
        for (let r = minRow; r <= maxRow; r++) {
          values.push(this.evalAddress(keyFromColRow(c, r)))
        }
      }
      return values
    }
    return [this.evaluate(argNode)]
  }

  evalCall(node) {
    const name = node.name.toUpperCase()
    if (!KNOWN_FUNCTIONS.has(name)) return errVal('#NAME?')

    if (name === 'ABS') {
      if (node.args.length !== 1) return errVal('#ERR!')
      const list = this.evalArgToList(node.args[0])
      const err = list.find((v) => v.t === 'err')
      if (err) return err
      if (list.length !== 1) return errVal('#VALUE!')
      const n = toNumber(list[0])
      if (n.t === 'err') return n
      return numVal(Math.abs(n.v))
    }

    if (name === 'IF') {
      if (node.args.length !== 3) return errVal('#ERR!')
      const condList = this.evalArgToList(node.args[0])
      const condErr = condList.find((v) => v.t === 'err')
      if (condErr) return condErr
      if (condList.length !== 1) return errVal('#VALUE!')
      const cond = toCondition(condList[0])
      if (cond.t === 'err') return cond
      const branch = cond.v ? node.args[1] : node.args[2]
      const branchList = this.evalArgToList(branch)
      const branchErr = branchList.find((v) => v.t === 'err')
      if (branchErr) return branchErr
      if (branchList.length !== 1) return errVal('#VALUE!')
      return branchList[0]
    }

    // SUM, MIN, MAX, AVG, COUNT
    if (node.args.length < 1) return errVal('#ERR!')
    const combined = node.args.flatMap((a) => this.evalArgToList(a))

    if (name === 'COUNT') {
      const err = combined.find((v) => v.t === 'err')
      if (err) return err
      return numVal(combined.filter((v) => v.t === 'num').length)
    }

    const nums = combined.map(toNumber)
    const numErr = nums.find((n) => n.t === 'err')
    if (numErr) return numErr
    const values = nums.map((n) => n.v)
    if (name === 'SUM') return finiteNum(values.reduce((a, b) => a + b, 0))
    if (name === 'MIN') return finiteNum(Math.min(...values))
    if (name === 'MAX') return finiteNum(Math.max(...values))
    if (name === 'AVG') return finiteNum(values.reduce((a, b) => a + b, 0) / values.length)
    throw new Error(`unreachable function ${name}`)
  }
}

function isComparisonOp(op) {
  return op === '=' || op === '<>' || op === '<' || op === '<=' || op === '>' || op === '>='
}

function applyComparison(op, cmp) {
  switch (op) {
    case '=':
      return cmp === 0
    case '<>':
      return cmp !== 0
    case '<':
      return cmp < 0
    case '<=':
      return cmp <= 0
    case '>':
      return cmp > 0
    case '>=':
      return cmp >= 0
    default:
      throw new Error(`unreachable comparison ${op}`)
  }
}

function applyArith(op, a, b) {
  switch (op) {
    case '+':
      return finiteNum(a + b)
    case '-':
      return finiteNum(a - b)
    case '*':
      return finiteNum(a * b)
    case '/':
      if (b === 0) return errVal('#DIV/0!')
      return finiteNum(a / b)
    case '^':
      return finiteNum(Math.pow(a, b))
    default:
      throw new Error(`unreachable operator ${op}`)
  }
}

/** Reads a value as an IF condition: TRUE/non-zero is true, FALSE/zero is
 * false, text is #VALUE!, errors pass through. */
function toCondition(v) {
  if (v.t === 'bool') return v
  const n = toNumber(v)
  if (n.t === 'err') return n
  return boolVal(n.v !== 0)
}
"}

