{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-ARkz8w/src/simulate.js","content":"/**
 * Runs a parsed limiter file's events through their routed policies and
 * renders either a `replay` transcript or a per-key `summary`.
 */

function matchRoute(routes, key) {
  for (const route of routes) {
    if (key.startsWith(route.prefix)) return route
  }
  return null
}

function verdictFor(route, tick, key) {
  if (route === null) return { allow: true, deniedBy: null }

  for (const policy of route.policies) policy.advance(key, tick)

  let deniedBy = null
  for (let i = 0; i < route.policies.length; i++) {
    if (!route.policies[i].canAllow(key)) {
      deniedBy = route.names[i]
      break
    }
  }

  if (deniedBy === null) {
    for (const policy of route.policies) policy.record(key, tick)
    return { allow: true, deniedBy: null }
  }
  return { allow: false, deniedBy }
}

export function replay({ routes, events }) {
  const lines = []
  for (const { tick, key } of events) {
    const route = matchRoute(routes, key)
    const verdict = verdictFor(route, tick, key)
    lines.push(
      verdict.allow ? `${tick} ${key} allow` : `${tick} ${key} deny ${verdict.deniedBy}`
    )
  }
  return lines.map((line) => line + '\n').join('')
}

export function summary({ routes, events }) {
  const totals = new Map()
  let totalAllowed = 0n
  let totalDenied = 0n

  for (const { tick, key } of events) {
    const route = matchRoute(routes, key)
    const verdict = verdictFor(route, tick, key)
    let entry = totals.get(key)
    if (entry === undefined) {
      entry = { allowed: 0n, denied: 0n }
      totals.set(key, entry)
    }
    if (verdict.allow) {
      entry.allowed += 1n
      totalAllowed += 1n
    } else {
      entry.denied += 1n
      totalDenied += 1n
    }
  }

  const keys = [...totals.keys()].sort()
  const lines = keys.map((key) => {
    const entry = totals.get(key)
    return `${key} allowed=${entry.allowed} denied=${entry.denied}\n`
  })
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}\n`)
  return lines.join('')
}
"}

