{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-ARkz8w/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { parse, ParseError } from './parse.js'
import { replay, summary } from './simulate.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    fail('usage: cli.js replay|summary')
    return
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')

  let parsed
  try {
    parsed = parse(input)
  } catch (err) {
    if (err instanceof ParseError) {
      fail(err.message)
      return
    }
    throw err
  }

  const output = mode === 'replay' ? replay(parsed) : summary(parsed)
  process.stdout.write(output)
  process.exit(0)
}

main()
"}

