{"file_path":"src/content.js","content":"/**
 * Classify a cell's raw content as a literal value or a formula AST.
 */

import { parseFormula } from './parser.js'
import { num, text, err } from './value.js'

const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const NUMBER_RE = /^-?[0-9]+(\.[0-9]+)?$/

function parseLiteral(raw) {
  if (raw === '') return num(0)
  if (NUMBER_RE.test(raw)) return num(parseFloat(raw))
  if (ERROR_TOKENS.has(raw)) return err(raw)
  return text(raw)
}

/**
 * Parse a cell's raw content. Returns either {kind:'literal', value} or
 * {kind:'formula', ast} where ast is null when the grammar rejects the body.
 */
export function parseContent(raw) {
  if (raw.startsWith('=')) {
    return { kind: 'formula', ast: parseFormula(raw.slice(1)) }
  }
  return { kind: 'literal', value: parseLiteral(raw) }
}
"}

