{"file_path":"src/evaluator.js","content":"/**
 * Evaluates cell content against a parsed sheet, with cycle detection and
 * memoization, and extracts the direct dependencies of a formula.
 */

import { parseLettersDigits, addressToString, compareCoords } from './address.js'
import { num, bool, err, isErr, finiteNum, toNumber, compareValues } from './value.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

const CALL_ARITY = {
  SUM: { min: 1, max: Infinity },
  MIN: { min: 1, max: Infinity },
  MAX: { min: 1, max: Infinity },
  COUNT: { min: 1, max: Infinity },
  AVG: { min: 1, max: Infinity },
  ABS: { min: 1, max: 1 },
  IF: { min: 3, max: 3 },
}

/**
 * Evaluates every declared cell against `sheet` (a Map of canonical address
 * to {ast|value, raw}), caching results and detecting cycles.
 */
export class Evaluator {
  constructor(sheet) {
    this.sheet = sheet
    this.cache = new Map()
    this.onStack = new Set()
  }

  cell(addr) {
    if (this.cache.has(addr)) return this.cache.get(addr)
    if (this.onStack.has(addr)) return err('#CYCLE!')
    const entry = this.sheet.get(addr)
    if (!entry) return num(0)
    this.onStack.add(addr)
    let result
    if (entry.content.kind === 'literal') {
      result = entry.content.value
    } else if (!entry.content.ast) {
      result = err('#ERR!')
    } else {
      result = this.evalNode(entry.content.ast)
    }
    this.onStack.delete(addr)
    this.cache.set(addr, result)
    return result
  }

  ref(node) {
    const coord = parseLettersDigits(node.letters, node.digits)
    if (!coord) return err('#REF!')
    return this.cell(addressToString(coord))
  }

  rangeCells(node) {
    const from = parseLettersDigits(node.from.letters, node.from.digits)
    const to = parseLettersDigits(node.to.letters, node.to.digits)
    if (!from || !to) return null
    const colMin = Math.min(from.col, to.col)
    const colMax = Math.max(from.col, to.col)
    const rowMin = Math.min(from.row, to.row)
    const rowMax = Math.max(from.row, to.row)
    const coords = []
    for (let col = colMin; col <= colMax; col++) {
      for (let row = rowMin; row <= rowMax; row++) coords.push({ col, row })
    }
    return coords
  }

  /** Evaluate an argument slot that must contribute a single scalar value. */
  evalScalarArg(node) {
    if (node.type === 'range') {
      const coords = this.rangeCells(node)
      if (!coords) return err('#REF!')
      if (coords.length !== 1) return err('#ERR!')
      return this.cell(addressToString(coords[0]))
    }
    return this.evalNode(node)
  }

  /** Flatten a variadic call's arguments left to right, expanding ranges. */
  collectArgValues(argNodes) {
    const flat = []
    for (const node of argNodes) {
      if (node.type === 'range') {
        const coords = this.rangeCells(node)
        if (!coords) {
          flat.push(err('#REF!'))
          continue
        }
        for (const coord of coords) flat.push(this.cell(addressToString(coord)))
      } else {
        flat.push(this.evalNode(node))
      }
    }
    return flat
  }

  evalNode(node) {
    switch (node.type) {
      case 'num':
        return num(node.value)
      case 'bool':
        return bool(node.value)
      case 'ref':
        return this.ref(node)
      case 'unary':
        return this.evalUnary(node)
      case 'bin':
        return this.evalBin(node)
      case 'call':
        return this.evalCall(node)
      default:
        throw new Error(`unreachable node type ${node.type}`)
    }
  }

  evalUnary(node) {
    const v = this.evalNode(node.arg)
    if (isErr(v)) return v
    const n = toNumber(v)
    if (isErr(n)) return n
    return finiteNum(node.op === '-' ? -n.v : n.v)
  }

  evalBin(node) {
    if (COMPARISON_OPS.has(node.op)) {
      const l = this.evalNode(node.left)
      if (isErr(l)) return l
      const r = this.evalNode(node.right)
      if (isErr(r)) return r
      const cmp = compareValues(l, r)
      return bool(applyComparison(node.op, cmp))
    }
    const l = this.evalNode(node.left)
    if (isErr(l)) return l
    const ln = toNumber(l)
    if (isErr(ln)) return ln
    const r = this.evalNode(node.right)
    if (isErr(r)) return r
    const rn = toNumber(r)
    if (isErr(rn)) return rn
    return finiteNum(applyArith(node.op, ln.v, rn.v))
  }

  evalCall(node) {
    const name = node.name
    const arity = CALL_ARITY[name]
    if (!arity) return err('#NAME?')
    const slots = node.args.length
    if (slots < arity.min || slots > arity.max) return err('#ERR!')

    if (name === 'IF') {
      const cond = this.evalScalarArg(node.args[0])
      if (isErr(cond)) return cond
      const condNum = toNumber(cond)
      if (isErr(condNum)) return condNum
      const branch = condNum.v !== 0 ? node.args[1] : node.args[2]
      return this.evalScalarArg(branch)
    }

    if (name === 'ABS') {
      const v = this.evalScalarArg(node.args[0])
      if (isErr(v)) return v
      const n = toNumber(v)
      if (isErr(n)) return n
      return finiteNum(Math.abs(n.v))
    }

    const flat = this.collectArgValues(node.args)
    for (const v of flat) {
      if (isErr(v)) return v
    }
    if (name === 'COUNT') {
      return num(flat.filter((v) => v.t === 'num').length)
    }
    const nums = []
    for (const v of flat) {
      const n = toNumber(v)
      if (isErr(n)) return n
      nums.push(n.v)
    }
    if (name === 'SUM') return finiteNum(nums.reduce((a, b) => a + b, 0))
    if (name === 'MIN') return finiteNum(Math.min(...nums))
    if (name === 'MAX') return finiteNum(Math.max(...nums))
    if (name === 'AVG') return finiteNum(nums.reduce((a, b) => a + b, 0) / nums.length)
    throw new Error(`unreachable function ${name}`)
  }
}

function applyComparison(op, cmp) {
  switch (op) {
    case '=':
      return cmp === 0
    case '<>':
      return cmp !== 0
    case '<':
      return cmp < 0
    case '<=':
      return cmp <= 0
    case '>':
      return cmp > 0
    case '>=':
      return cmp >= 0
    default:
      throw new Error(`unreachable comparison ${op}`)
  }
}

function applyArith(op, a, b) {
  switch (op) {
    case '+':
      return a + b
    case '-':
      return a - b
    case '*':
      return a * b
    case '/':
      return a / b
    case '^':
      return Math.pow(a, b)
    default:
      throw new Error(`unreachable operator ${op}`)
  }
}

/** Collect the distinct in-range addresses a formula AST names directly. */
export function collectDeps(ast) {
  const map = new Map()
  const add = (coord) => map.set(addressToString(coord), coord)

  const walk = (node) => {
    switch (node.type) {
      case 'num':
      case 'bool':
        return
      case 'ref': {
        const coord = parseLettersDigits(node.letters, node.digits)
        if (coord) add(coord)
        return
      }
      case 'range': {
        const from = parseLettersDigits(node.from.letters, node.from.digits)
        const to = parseLettersDigits(node.to.letters, node.to.digits)
        if (!from || !to) return
        const colMin = Math.min(from.col, to.col)
        const colMax = Math.max(from.col, to.col)
        const rowMin = Math.min(from.row, to.row)
        const rowMax = Math.max(from.row, to.row)
        for (let col = colMin; col <= colMax; col++) {
          for (let row = rowMin; row <= rowMax; row++) add({ col, row })
        }
        return
      }
      case 'unary':
        walk(node.arg)
        return
      case 'bin':
        walk(node.left)
        walk(node.right)
        return
      case 'call':
        for (const arg of node.args) walk(arg)
        return
      default:
        throw new Error(`unreachable node type ${node.type}`)
    }
  }

  walk(ast)
  return Array.from(map.values()).sort(compareCoords)
}
"}

