{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-M4T14E/src/parse.js","content":"/**
 * Parsing and validation of an election description read from standard input.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

/** Raised for any input that fails validation; carries the message to print. */
export class ParseError extends Error {}

/**
 * Parses `text` into `{ candidates, ballots }`, where `candidates` is the
 * declared names in declaration order and `ballots` is a list of
 * `{ count, names }`. Throws `ParseError` on the first invalid line, with a
 * message matching the specification exactly (including any `line N:` prefix).
 */
export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  const declared = new Set()
  const ballots = []
  let sawBallot = false

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'candidates') {
      if (candidates !== null || sawBallot) {
        throw new ParseError(`line ${lineNumber}: candidates must be declared once, before any ballot`)
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        throw new ParseError(`line ${lineNumber}: expected candidates <name>...`)
      }
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          throw new ParseError(`line ${lineNumber}: invalid candidate name ${name}`)
        }
        if (declared.has(name)) {
          throw new ParseError(`line ${lineNumber}: candidate ${name} is declared twice`)
        }
        declared.add(name)
      }
      candidates = names
    } else if (word === 'ballot') {
      if (candidates === null) {
        throw new ParseError(`line ${lineNumber}: candidates must be declared once, before any ballot`)
      }
      sawBallot = true
      const rest = tokens.slice(1)
      if (rest.length < 2) {
        throw new ParseError(`line ${lineNumber}: expected ballot <count> <candidate>...`)
      }
      const [countStr, ...names] = rest
      if (!COUNT_RE.test(countStr)) {
        throw new ParseError(`line ${lineNumber}: count must be a positive integer`)
      }
      const seen = new Set()
      for (const name of names) {
        if (!declared.has(name)) {
          throw new ParseError(`line ${lineNumber}: unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          throw new ParseError(`line ${lineNumber}: candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count: Number.parseInt(countStr, 10), names })
    } else {
      throw new ParseError(`line ${lineNumber}: unknown directive ${word}`)
    }
  }

  if (candidates === null) {
    throw new ParseError('no candidates')
  }

  return { candidates, ballots }
}
"}

