      if (!COUNT_RE.test(countStr)) {
        throw new ParseError(`line ${lineNumber}: count must be a positive integer`)
      }
      const seen = new Set()
      for (const name of names) {
        if (!declared.has(name)) {
          throw new ParseError(`line ${lineNumber}: unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          throw new ParseError(`line ${lineNumber}: candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count: Number.parseInt(countStr, 10), names })
    } else {
      throw new ParseError(`line ${lineNumber}: unknown directive ${word}`)
    }
  }

  if (candidates === null) {
    throw new ParseError('no candidates')
  }

  return { candidates, ballots }
