 * Instant-runoff counting over a parsed election.
 */

/**
 * Counts `election` round by round. Returns `{ rounds, winner }`, where
 * `rounds` is a list of `{ votes, exhausted, eliminated }` in the order
 * counted: `votes` is a Map from every candidate continuing at the start of
 * that round to their vote count, `exhausted` is the number of ballots that
 * counted for nobody, and `eliminated` is the name removed after that round
 * or `null` when the round instead ended the election. `winner` is the name
 * that reached a majority, or `null` when none ever did.
 */
export function countElection(election) {
  const { candidates, ballots } = election
  let continuing = new Set(candidates)
  const rounds = []
  const history = []
  let winner = null

  for (;;) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        votes.set(choice, votes.get(choice) + ballot.count)
      }
    }

    history.push(votes)
    const activeTotal = [...votes.values()].reduce((a, b) => a + b, 0)

    if (activeTotal === 0) {
      rounds.push({ votes, exhausted, eliminated: null })
      break
    }

    let majority = null
    for (const [name, count] of votes) {
      if (count * 2 > activeTotal) majority = name
    }

    if (majority !== null) {
      winner = majority
      rounds.push({ votes, exhausted, eliminated: null })
      break
    }

    const minVotes = Math.min(...votes.values())
    const fewest = [...votes.keys()].filter((name) => votes.get(name) === minVotes)
    const eliminated = fewest.length === 1 ? fewest[0] : breakTie(fewest, history)

    rounds.push({ votes, exhausted, eliminated })
    continuing = new Set([...continuing].filter((name) => name !== eliminated))
  }

  return { rounds, winner }
}

/**
 * Resolves a tie for fewest votes among `tied` by comparing their counts
 * across `history` from the first round onwards, narrowing to whoever had
 * the fewest at the first round where they were not all equal, and
 * repeating from the first round again until no round separates the
 * survivors. Returns the one to eliminate, picking by name (sorting last by
 * code point) when history never separates them.
 */
function breakTie(tied, history) {
  let survivors = tied
  for (;;) {
    let splitRound = null
    for (const votes of history) {
      const counts = survivors.map((name) => votes.get(name))
      if (!counts.every((count) => count === counts[0])) {
        splitRound = votes
        break
      }
    }
    if (splitRound === null) break
    const minVotes = Math.min(...survivors.map((name) => splitRound.get(name)))
    survivors = survivors.filter((name) => splitRound.get(name) === minVotes)
    if (survivors.length === 1) break
  }
  return survivors.length === 1 ? survivors[0] : survivors.reduce((a, b) => (a > b ? a : b))
}
