{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-M4T14E/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { parseElection, ParseError } from './parse.js'
import { countElection } from './count.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function formatRound(number, round) {
  const entries = [...round.votes].sort(([nameA, countA], [nameB, countB]) => {
    if (countA !== countB) return countB - countA
    return nameA < nameB ? -1 : nameA > nameB ? 1 : 0
  })
  const parts = entries.map(([name, count]) => `${name}=${count}`)
  parts.push(`exhausted=${round.exhausted}`)
  const lines = [`round ${number}: ${parts.join(' ')}`]
  if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
  return lines
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
    fail('usage: cli.js rounds|tally')
  }

  const input = readFileSync(0, 'utf8')

  let election
  try {
    election = parseElection(input)
  } catch (error) {
    if (error instanceof ParseError) fail(error.message)
    throw error
  }

  const { rounds, winner } = countElection(election)
  const outcome = winner === null ? 'no winner' : `winner ${winner}`

  const lines = []
  if (mode === 'rounds') {
    rounds.forEach((round, index) => lines.push(...formatRound(index + 1, round)))
  } else {
    lines.push(`rounds ${rounds.length}`)
  }
  lines.push(outcome)

  process.stdout.write(lines.map((line) => `${line}\n`).join(''))
}

main()
"}

