 * Reads non-formula cell content into a value: empty content and undeclared
 * cells are the number 0, the six error tokens are the matching error,
 * plain numbers are numbers, and everything else is text.
 */

const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const NUMBER_RE = /^-?\d+(\.\d+)?$/

export function parseLiteral(content) {
  if (content === '') return { t: 'number', v: 0 }
  if (ERROR_TOKENS.has(content)) return { t: 'error', v: content }
  if (NUMBER_RE.test(content)) return { t: 'number', v: Number(content) }
  return { t: 'text', v: content }
}
"}

