 * Walks a parsed formula's syntax tree to list the cells it names directly
 * (ranges expanded to every cell they cover), ordered by column then row.
 * This is purely syntactic: it does not evaluate the formula, so it also
 * names cells a taken `IF` branch would not visit.
 */

import { resolveAddressText, colIndex, indexToCol } from './address.js'

export function collectDeps(ast) {
  const found = new Map() // canonical -> { col, row }

  function addAddress(text) {
    const r = resolveAddressText(text)
    if (r.inRange) found.set(r.canonical, { col: colIndex(r.col), row: r.row })
  }

  function addRange(a, b) {
    const ra = resolveAddressText(a)
    const rb = resolveAddressText(b)
    if (!ra.inRange || !rb.inRange) return
    const c1 = colIndex(ra.col)
    const c2 = colIndex(rb.col)
    const cMin = Math.min(c1, c2)
    const cMax = Math.max(c1, c2)
    const rMin = Math.min(ra.row, rb.row)
    const rMax = Math.max(ra.row, rb.row)
    for (let c = cMin; c <= cMax; c++) {
      const colLetters = indexToCol(c)
      for (let r = rMin; r <= rMax; r++) {
        found.set(colLetters + r, { col: c, row: r })
      }
    }
  }

  function walk(node) {
    switch (node.type) {
      case 'addr':
        addAddress(node.text)
        break
      case 'range':
        addRange(node.a, node.b)
        break
      case 'unary':
        walk(node.node)
        break
      case 'bin':
        walk(node.left)
        walk(node.right)
        break
      case 'call':
        node.args.forEach(walk)
        break
      default:
        break
    }
  }

  walk(ast)

  const list = [...found.entries()].map(([addr, pos]) => ({ addr, ...pos }))
  list.sort((x, y) => x.col - y.col || x.row - y.row)
  return list.map((e) => e.addr)
}
"}

