 * RFC 3986 generic-syntax parsing, normalization and reference resolution.
 */

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

/** Raised when a `%` in a component is not followed by two hex digits. */
export class PercentEncodingError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

function asciiLower(s) {
  return s.replace(/[A-Z]/g, (c) => String.fromCharCode(c.charCodeAt(0) + 32))
}

/**
 * Split a URI reference into its five generic-syntax components. `null`
 * marks an absent component; `''` marks one that was written empty.
 */
export function parseReference(s) {
  let rest = s
  let scheme = null
  let schemeEnd = -1
  for (let i = 0; i < s.length; i++) {
    const c = s[i]
    if (c === ':') {
      schemeEnd = i
      break
    }
    if (c === '/' || c === '?' || c === '#') break
  }
  if (schemeEnd !== -1) {
    scheme = s.slice(0, schemeEnd)
    rest = s.slice(schemeEnd + 1)
  }

  let authority = null
  if (rest.startsWith('//')) {
    let i = 2
    while (i < rest.length && rest[i] !== '/' && rest[i] !== '?' && rest[i] !== '#') i++
    authority = rest.slice(2, i)
    rest = rest.slice(i)
  }

  const hIdx = rest.indexOf('#')
  const prefix = hIdx === -1 ? rest : rest.slice(0, hIdx)
  const fragment = hIdx === -1 ? null : rest.slice(hIdx + 1)
  const qIdx = prefix.indexOf('?')
  const path = qIdx === -1 ? prefix : prefix.slice(0, qIdx)
  const query = qIdx === -1 ? null : prefix.slice(qIdx + 1)

  return { scheme, authority, path, query, fragment }
}

/** Split an authority into userinfo, host and port per the task's rules. */
export function splitAuthority(authority) {
  let userinfo = null
  let rest = authority
  const atIdx = authority.lastIndexOf('@')
  if (atIdx !== -1) {
    userinfo = authority.slice(0, atIdx)
    rest = authority.slice(atIdx + 1)
  }
  const bracketIdx = rest.lastIndexOf(']')
  const searchStart = bracketIdx === -1 ? 0 : bracketIdx + 1
  const colonIdx = rest.indexOf(':', searchStart)
  let host, port
  if (colonIdx !== -1) {
    host = rest.slice(0, colonIdx)
    port = rest.slice(colonIdx + 1)
  } else {
    host = rest
    port = null
  }
  return { userinfo, host, port }
}

function serialize({ scheme, authority, path, query, fragment }) {
  let out = ''
  if (scheme !== null) out += scheme + ':'
  if (authority !== null) out += '//' + authority
  out += path
  if (query !== null) out += '?' + query
  if (fragment !== null) out += '#' + fragment
  return out
}

function isUnreserved(ch) {
  return /[A-Za-z0-9\-._~]/.test(ch)
}

/** Uppercase `%XX` hex digits and decode the triplet when it is unreserved. */
function normalizePercent(s, component) {
  let out = ''
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '%') {
      const hex = s.slice(i + 1, i + 3)
      if (!/^[0-9A-Fa-f]{2}$/.test(hex)) throw new PercentEncodingError(component)
      const upper = hex.toUpperCase()
      const ch = String.fromCharCode(parseInt(upper, 16))
      out += isUnreserved(ch) ? ch : '%' + upper
      i += 2
    } else {
      out += s[i]
    }
  }
  return out
}

/** Remove `.` and `..` segments from a path per RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  const output = []
  let input = path
  while (input !== '') {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output.pop()
    } else if (input === '/..') {
      input = '/'
      output.pop()
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let idx
      if (input[0] === '/') {
        idx = input.indexOf('/', 1)
      } else {
        idx = input.indexOf('/')
      }
      if (idx === -1) idx = input.length
      output.push(input.slice(0, idx))
      input = input.slice(idx)
    }
  }
  return output.join('')
}

/**
 * Normalize an already-parsed reference and return the printable string.
 * Throws `PercentEncodingError` for a truncated `%XX`, checking path,
 * userinfo, host, query and fragment in that order.
 */
export function normalizeComponents(comp) {
  const scheme = comp.scheme !== null ? asciiLower(comp.scheme) : null
  const path0 = normalizePercent(comp.path, 'path')

  let userinfo = null
  let host = null
  let port = null
  if (comp.authority !== null) {
    const split = splitAuthority(comp.authority)
    userinfo = split.userinfo !== null ? normalizePercent(split.userinfo, 'userinfo') : null
    host = normalizePercent(split.host, 'host')
    port = split.port
  }

  const query = comp.query !== null ? normalizePercent(comp.query, 'query') : null
  const fragment = comp.fragment !== null ? normalizePercent(comp.fragment, 'fragment') : null

  let authority = comp.authority !== null ? '' : null
  if (comp.authority !== null) {
    host = asciiLower(host)
    if (port === '' || port === null) {
      port = null
    } else if (scheme !== null && DEFAULT_PORTS[scheme] === port) {
      port = null
    }
    authority = (userinfo !== null ? userinfo + '@' : '') + host + (port !== null ? ':' + port : '')
  }

  let path = removeDotSegments(path0)
  if (authority !== null && path === '') path = '/'

  return serialize({ scheme, authority, path, query, fragment })
}

/** Normalize a URI reference given as text. */
export function normalize(text) {
  return normalizeComponents(parseReference(text))
}

function merge(baseAuthority, basePath, refPath) {
  if (baseAuthority !== null && basePath === '') return '/' + refPath
  const idx = basePath.lastIndexOf('/')
  if (idx === -1) return refPath
  return basePath.slice(0, idx + 1) + refPath
}

/** Resolve `ref` against `base` per RFC 3986 section 5.2.2 (strict). */
export function resolveReference(base, ref) {
  const t = {}
  if (ref.scheme !== null) {
    t.scheme = ref.scheme
    t.authority = ref.authority
    t.path = removeDotSegments(ref.path)
    t.query = ref.query
  } else if (ref.authority !== null) {
    t.scheme = base.scheme
    t.authority = ref.authority
