{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-VujuMy/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { parseReference, normalize, resolve, PercentEncodingError } from './uri.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.slice(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function splitRecords(input) {
  const parts = input.split('\n')
  if (parts.length > 0 && parts[parts.length - 1] === '') parts.pop()
  return parts
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
    fail('usage: cli.js normalize|resolve')
  }

  const input = readStdin()
  const records = splitRecords(input)
  const results = []

  for (let i = 0; i < records.length; i++) {
    const n = i + 1
    const record = records[i]
    try {
      if (mode === 'normalize') {
        results.push(normalize(record))
      } else {
        const spaceIdx = record.indexOf(' ')
        if (spaceIdx === -1) fail(`line ${n}: expected a base and a reference`)
        const baseText = record.slice(0, spaceIdx)
        const refText = record.slice(spaceIdx + 1)
        if (parseReference(baseText).scheme === null) fail(`line ${n}: the base has no scheme`)
        results.push(resolve(baseText, refText))
      }
    } catch (err) {
      if (err instanceof PercentEncodingError) fail(`line ${n}: ${err.message}`)
      throw err
    }
  }

  process.stdout.write(results.map((r) => r + '\n').join(''))
  process.exit(0)
}

main()
"}

