 * Splits raw standard input text into the three documents (mine, base,
 * theirs) separated by lines that are exactly `%%%`.
 */

/**
 * @param {string} text raw standard input
 * @returns {string[][]|null} the three documents, or null when the input
 *   does not hold exactly three parts
 */
export function parseInput(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }

  if (parts.length !== 3) return null
  return parts
}
"}

