{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-WNn3uy/src/regions.js","content":"import { computeChanges, computeMatches } from './lcs.js'

/**
 * @param {string[]} a
 * @param {string[]} b
 * @returns {boolean}
 */
function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * Runs a side's replacement across a region: the lines from the smallest
 * start of its own changes, moved back by however far the region begins
 * before those changes do in the base, to the largest end of its own
 * changes, moved forward by however far the region ends after them. A side
 * untouched anywhere in the region keeps the base's lines for it.
 *
 * @param {{baseStart: number, baseEnd: number}} region
 * @param {{baseStart: number, baseEnd: number, sideStart: number, sideEnd: number}[]} members
 * @param {string[]} doc
 * @param {string[]} base
 * @returns {string[]}
 */
function sideLines(region, members, doc, base) {
  if (members.length === 0) return base.slice(region.baseStart, region.baseEnd)
  const first = members[0]
  const last = members[members.length - 1]
  const frontExtension = first.baseStart - region.baseStart
  const backExtension = region.baseEnd - last.baseEnd
  return doc.slice(first.sideStart - frontExtension, last.sideEnd + backExtension)
}

/**
 * Splits the base into the stable stretches and merge regions described by
 * the two sides' changes, in base order.
 *
 * Each element is one of:
 *  - `{ type: 'stable', lines }` — a stretch of base lines the merge keeps
 *  - `{ type: 'mine' | 'theirs' | 'both', lines }` — a region that resolved
 *    cleanly
 *  - `{ type: 'conflict', mine, base, theirs }` — a region neither side's
 *    lines nor the base's lines could settle
 *
 * @param {string[]} mine
 * @param {string[]} base
 * @param {string[]} theirs
 * @returns {object[]}
 */
export function buildSegments(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine, computeMatches(base, mine)).map(c => ({ ...c, side: 'mine' }))
  const theirsChanges = computeChanges(base, theirs, computeMatches(base, theirs)).map(c => ({ ...c, side: 'theirs' }))

  const allChanges = mineChanges.concat(theirsChanges).sort((a, b) => a.baseStart - b.baseStart)

  const regions = []
  let idx = 0
  while (idx < allChanges.length) {
    const members = [allChanges[idx]]
    let regionStart = allChanges[idx].baseStart
    let regionEnd = allChanges[idx].baseEnd
    idx++
    while (idx < allChanges.length && allChanges[idx].baseStart <= regionEnd) {
      regionEnd = Math.max(regionEnd, allChanges[idx].baseEnd)
      members.push(allChanges[idx])
      idx++
    }
    regions.push({ baseStart: regionStart, baseEnd: regionEnd, members })
  }

  const segments = []
  let cursor = 0
  for (const region of regions) {
    if (region.baseStart > cursor) segments.push({ type: 'stable', lines: base.slice(cursor, region.baseStart) })

    if (region.members.length === 1) {
      const only = region.members[0]
      const doc = only.side === 'mine' ? mine : theirs
      segments.push({ type: only.side, lines: doc.slice(only.sideStart, only.sideEnd) })
    } else {
      const mineMembers = region.members.filter(m => m.side === 'mine')
      const theirsMembers = region.members.filter(m => m.side === 'theirs')
      const mineLines = sideLines(region, mineMembers, mine, base)
      const theirsLines = sideLines(region, theirsMembers, theirs, base)
      const baseLines = base.slice(region.baseStart, region.baseEnd)

      if (arraysEqual(mineLines, theirsLines)) segments.push({ type: 'both', lines: mineLines })
      else if (arraysEqual(mineLines, baseLines)) segments.push({ type: 'theirs', lines: theirsLines })
      else if (arraysEqual(theirsLines, baseLines)) segments.push({ type: 'mine', lines: mineLines })
      else segments.push({ type: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines })
    }

    cursor = region.baseEnd
  }
  if (cursor < base.length) segments.push({ type: 'stable', lines: base.slice(cursor, base.length) })

  return segments
}
"}

