{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-WNn3uy/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { parseInput } from './parse.js'
import { buildSegments } from './regions.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.has(mode)) {
    fail('error: usage: cli.js merge|merge2|regions')
  }

  const input = readFileSync(0, 'utf8')
  const parts = parseInput(input)
  if (parts === null) fail('error: expected three parts separated by %%%')

  const [mine, base, theirs] = parts
  const segments = buildSegments(mine, base, theirs)

  const out = []
  let conflicted = false

  for (const segment of segments) {
    if (segment.type === 'conflict') conflicted = true

    if (mode === 'regions') {
      out.push(formatRegionLine(segment))
    } else {
      formatMergeLines(segment, mode === 'merge', out)
    }
  }

  process.stdout.write(out.length === 0 ? '' : `${out.join('\n')}\n`)
  process.exit(conflicted ? 1 : 0)
}

function formatRegionLine(segment) {
  if (segment.type === 'conflict') {
    return `conflict mine=${segment.mine.length} base=${segment.base.length} theirs=${segment.theirs.length}`
  }
  return `${segment.type} ${segment.lines.length}`
}

function formatMergeLines(segment, withBase, out) {
  if (segment.type !== 'conflict') {
    out.push(...segment.lines)
    return
  }
  out.push('<<<<<<< mine', ...segment.mine)
  if (withBase) out.push('||||||| base', ...segment.base)
  out.push('=======', ...segment.theirs, '>>>>>>> theirs')
}

main()
"}

