function scanString(s, pos) {
  s.advance() // opening quote
  let decoded = ''
  for (;;) {
    if (s.i >= s.length) throw new LexError(pos, 'unterminated string')
    const c = s.peek()
    if (c === '"') {
      s.advance()
      break
    }
    if (c === '\n') throw new LexError(s.pos(), 'newline in string')
    if (c === '\\') {
      const bpos = s.pos()
      s.advance() // backslash
      if (s.i >= s.length) throw new LexError(pos, 'unterminated string')
      const e = s.peek()
      if (e === 'n') {
        decoded += '\n'
        s.advance()
      } else if (e === 't') {
        decoded += '\t'
        s.advance()
      } else if (e === 'r') {
        decoded += '\r'
        s.advance()
      } else if (e === '\\') {
        decoded += '\\'
        s.advance()
      } else if (e === '"') {
        decoded += '"'
        s.advance()
      } else if (e === '0') {
        decoded += '\0'
        s.advance()
      } else if (e === 'x') {
        s.advance()
        const h1 = s.peek()
        const h2 = s.peek(1)
        if (isHexDigit(h1) && isHexDigit(h2)) {
          s.advance()
          s.advance()
          decoded += String.fromCharCode(parseInt(h1 + h2, 16))
