{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-j6RfRK/src/parse.js","content":"import { CliError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses build-graph text into a task cost map and a dependency map, or
 * throws a `CliError` describing the first malformed line or the first
 * dependency naming an undeclared task.
 */
export function parseInput(input) {
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map() // name -> { cost, line }
  const depLines = [] // { line, target, deps: string[] } in input order

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`error: line ${lineNumber}: expected task <name> <cost>`, 2)
      }
      const [, name, costText] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(`error: line ${lineNumber}: invalid task name ${name}`, 2)
      }
      if (!COST_RE.test(costText)) {
        throw new CliError(`error: line ${lineNumber}: cost must be a non-negative integer`, 2)
      }
      if (tasks.has(name)) {
        throw new CliError(`error: line ${lineNumber}: task ${name} is declared twice`, 2)
      }
      tasks.set(name, { cost: parseInt(costText, 10), line: lineNumber })
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`error: line ${lineNumber}: expected dep <name> <dependency>...`, 2)
      }
      const names = words.slice(1)
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          throw new CliError(`error: line ${lineNumber}: invalid task name ${name}`, 2)
        }
      }
      depLines.push({ line: lineNumber, target: names[0], deps: names.slice(1) })
    } else {
      throw new CliError(`error: line ${lineNumber}: unknown directive ${directive}`, 2)
    }
  }

  for (const { target, deps } of depLines) {
    for (const name of [target, ...deps]) {
      if (!tasks.has(name)) {
        throw new CliError(`error: unknown task ${name}`, 2)
      }
    }
  }

  const deps = new Map()
  for (const name of tasks.keys()) deps.set(name, new Set())
  for (const { target, deps: names } of depLines) {
    const set = deps.get(target)
    for (const name of names) set.add(name)
  }

  const depsSorted = new Map()
  for (const [name, set] of deps) depsSorted.set(name, [...set].sort())

  return { tasks, deps: depsSorted }
}
"}

