  for (const name of tasks.keys()) deps.set(name, new Set())
  for (const { target, deps: names } of depLines) {
    const set = deps.get(target)
    for (const name of names) set.add(name)
  }

  const depsSorted = new Map()
  for (const [name, set] of deps) depsSorted.set(name, [...set].sort())

  return { tasks, deps: depsSorted }
}
