 * Errors raised while parsing a limiter file. Each carries the 1-based line
 * number of the offending line so the CLI can format `error: line N: ...`.
 */
export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}
"}

{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-m4ONxQ/src/policies.js","content":"/**
 * The two policy kinds a limiter file can declare. Each policy keeps one
 * independent state per key, created lazily the first time that key reaches
 * the policy.
 */

/**
 * A token bucket. Tokens are tracked scaled by `per` so that the exact
 * fractional refill (`refill * n / per`) never needs rounding: one whole
 * token is represented by `per` scaled units.
 */
export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.full = capacity * per
    this.states = new Map()
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (!state) {
      state = { scaled: this.full, lastTick: tick }
      this.states.set(key, state)
      return
    }
    const elapsed = tick - state.lastTick
    if (elapsed > 0n) {
      state.scaled += this.refill * elapsed
      if (state.scaled > this.full) state.scaled = this.full
      state.lastTick = tick
    }
  }

  allow(key) {
    return this.states.get(key).scaled >= this.per
  }

  record(key) {
    this.states.get(key).scaled -= this.per
  }
}

/** A sliding window. Remembers the ticks of the requests it recorded for each key. */
export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  advance(key, tick) {
    let ticks = this.states.get(key)
