  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.full = capacity * per
    this.states = new Map()
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (!state) {
      state = { scaled: this.full, lastTick: tick }
      this.states.set(key, state)
      return
