{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-m4ONxQ/src/parser.js","content":"/**
 * Parses a limiter file into declared policies, routes and events. Raises a
 * {@link ParseError} tagged with the offending line number as soon as it
 * finds a problem, matching the "stop at the first failure" contract of the
 * CLI.
 */
import { ParseError } from './errors.js'
import { TokenBucket, SlidingWindow } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_./:-]+$/
const COUNT_RE = /^(0|[1-9][0-9]*)$/

function parseCount(text, field, min, line) {
  if (!COUNT_RE.test(text) || BigInt(text) < min) {
    throw new ParseError(line, `${field} must be an integer of at least ${min}`)
  }
  return BigInt(text)
}

/**
 * @returns {{ policies: Map<string, TokenBucket|SlidingWindow>, routes: Array<{prefix: string, policyNames: string[]}>, events: Array<{tick: bigint, key: string}> }}
 */
export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routes = []
  const routePrefixes = new Set()
  const events = []
  let firstEventSeen = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket') {
      if (firstEventSeen) throw new ParseError(lineNo, 'declarations must come before the first event')
      if (tokens.length !== 5) throw new ParseError(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      const [, name, capacityText, refillText, perText] = tokens
      if (!NAME_RE.test(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
      const capacity = parseCount(capacityText, 'capacity', 1n, lineNo)
      const refill = parseCount(refillText, 'refill', 0n, lineNo)
      const per = parseCount(perText, 'per', 1n, lineNo)
      if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
      policies.set(name, new TokenBucket(capacity, refill, per))
    } else if (directive === 'window') {
      if (firstEventSeen) throw new ParseError(lineNo, 'declarations must come before the first event')
      if (tokens.length !== 4) throw new ParseError(lineNo, 'expected window <name> <limit> <span>')
      const [, name, limitText, spanText] = tokens
      if (!NAME_RE.test(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
      const limit = parseCount(limitText, 'limit', 0n, lineNo)
      const span = parseCount(spanText, 'span', 1n, lineNo)
      if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
      policies.set(name, new SlidingWindow(limit, span))
    } else if (directive === 'route') {
      if (firstEventSeen) throw new ParseError(lineNo, 'declarations must come before the first event')
      if (tokens.length < 3) throw new ParseError(lineNo, 'expected route <prefix> <policy>...')
      const prefix = tokens[1]
      if (!NAME_RE.test(prefix)) throw new ParseError(lineNo, `invalid route prefix ${prefix}`)
      const policyNames = tokens.slice(2)
      for (const name of policyNames) {
        if (!policies.has(name)) throw new ParseError(lineNo, `unknown policy ${name}`)
      }
      if (routePrefixes.has(prefix)) throw new ParseError(lineNo, `prefix ${prefix} is routed twice`)
      routePrefixes.add(prefix)
      routes.push({ prefix, policyNames })
    } else if (directive === 'event') {
      firstEventSeen = true
      if (tokens.length !== 3) throw new ParseError(lineNo, 'expected event <tick> <key>')
      const [, tickText, key] = tokens
      const tick = parseCount(tickText, 'tick', 0n, lineNo)
      if (lastTick !== null && tick < lastTick) {
        throw new ParseError(lineNo, `tick ${tickText} is before tick ${lastTick}`)
      }
      if (!NAME_RE.test(key)) throw new ParseError(lineNo, `invalid key ${key}`)
      lastTick = tick
      events.push({ tick, key })
    } else {
      throw new ParseError(lineNo, `unknown directive ${directive}`)
    }
  }

  return { policies, routes, events }
}
"}

