{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-m4ONxQ/src/simulate.js","content":"/**
 * Replays a parsed limiter file's events against its policies and routes,
 * yielding one verdict per event in log order.
 */

/**
 * Finds the route whose prefix is the longest match for a key, or
 * `undefined` if no route's prefix matches.
 */
function matchRoute(routes, key) {
  let best
  for (const route of routes) {
    if (key.startsWith(route.prefix)) {
      if (!best || route.prefix.length > best.prefix.length) best = route
    }
  }
  return best
}

/**
 * @returns {Array<{tick: bigint, key: string, allowed: boolean, deniedBy: string|null}>}
 */
export function simulate({ policies, routes, events }) {
  const verdicts = []
  for (const { tick, key } of events) {
    const route = matchRoute(routes, key)
    if (!route) {
      verdicts.push({ tick, key, allowed: true, deniedBy: null })
      continue
    }
    const policyList = route.policyNames.map((name) => policies.get(name))
    for (const policy of policyList) policy.advance(key, tick)

    let deniedBy = null
    for (let i = 0; i < policyList.length; i++) {
      if (!policyList[i].allow(key)) {
        deniedBy = route.policyNames[i]
        break
      }
    }

    if (deniedBy === null) {
      for (const policy of policyList) policy.record(key, tick)
      verdicts.push({ tick, key, allowed: true, deniedBy: null })
    } else {
      verdicts.push({ tick, key, allowed: false, deniedBy })
    }
  }
  return verdicts
}
"}

