{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-m4ONxQ/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { parse } from './parser.js'
import { simulate } from './simulate.js'
import { ParseError } from './errors.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  let bytesRead
  while (true) {
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'replay' && mode !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  const input = readStdin()

  let parsed
  try {
    parsed = parse(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const verdicts = simulate(parsed)

  if (mode === 'replay') {
    const lines = verdicts.map((v) =>
      v.allowed ? `${v.tick} ${v.key} allow` : `${v.tick} ${v.key} deny ${v.deniedBy}`
    )
    process.stdout.write(lines.length ? lines.join('\n') + '\n' : '')
  } else {
    const totals = new Map()
    for (const v of verdicts) {
      let t = totals.get(v.key)
      if (!t) {
        t = { allowed: 0, denied: 0 }
        totals.set(v.key, t)
      }
      if (v.allowed) t.allowed++
      else t.denied++
    }
    const keys = [...totals.keys()].sort()
    const lines = []
    let totalAllowed = 0
    let totalDenied = 0
    for (const key of keys) {
      const t = totals.get(key)
      lines.push(`${key} allowed=${t.allowed} denied=${t.denied}`)
      totalAllowed += t.allowed
      totalDenied += t.denied
    }
    lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
    process.stdout.write(lines.join('\n') + '\n')
  }
}

main(process.argv.slice(2))
"}

