/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { buildSegments } from './merge.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function parseDocuments(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }
  if (parts.length !== 3) fail('error: expected three parts separated by %%%')
  return parts
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  let bytesRead
  do {
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead > 0) chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  } while (bytesRead > 0)
  return Buffer.concat(chunks).toString('utf8')
}

function writeConflict(out, segment, includeBase) {
  out.push('<<<<<<< mine')
  out.push(...segment.mineLines)
  if (includeBase) {
    out.push('||||||| base')
    out.push(...segment.baseLines)
  }
  out.push('=======')
  out.push(...segment.theirsLines)
  out.push('>>>>>>> theirs')
}

function runMerge(segments, includeBase) {
  const out = []
  let conflict = false
  for (const segment of segments) {
    if (segment.kind === 'conflict') {
      conflict = true
      writeConflict(out, segment, includeBase)
    } else {
      out.push(...segment.lines)
    }
  }
  return { out, conflict }
}

function runRegions(segments) {
  const out = []
  let conflict = false
  for (const segment of segments) {
    if (segment.kind === 'conflict') {
      conflict = true
      out.push(`conflict mine=${segment.mineLines.length} base=${segment.baseLines.length} theirs=${segment.theirsLines.length}`)
    } else {
      out.push(`${segment.kind} ${segment.lines.length}`)
    }
  }
  return { out, conflict }
}

function main() {
  const [mode] = process.argv.slice(2)
  if (!MODES.has(mode)) fail('error: usage: cli.js merge|merge2|regions')

  const input = readStdin()
  const [mine, base, theirs] = parseDocuments(input)
  const segments = buildSegments(mine, base, theirs)

  const { out, conflict } =
    mode === 'regions' ? runRegions(segments) : runMerge(segments, mode === 'merge')

  const text = out.length === 0 ? '' : `${out.join('\n')}\n`
  process.stdout.write(text)
  process.exit(conflict ? 1 : 0)
}

main()
"}

