 * A hand-written scanner for the toy language described by the task. It reads
 * a whole source string and turns it into a flat list of tokens, or throws a
 * {@link LexError} carrying the line, column and reason of the first problem
 * it meets.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

// Longest match wins, so two-character operators are listed before the
// one-character ones they would otherwise shadow.
const PUNCTUATORS = [
  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
]

const TAB_WIDTH = 4

function isLetter(ch) {
  return ch !== undefined && /[A-Za-z]/.test(ch)
}

function isDigit(ch) {
  return ch !== undefined && /[0-9]/.test(ch)
}

function isHexDigit(ch) {
  return ch !== undefined && /[0-9a-fA-F]/.test(ch)
}

function isOctDigit(ch) {
  return ch !== undefined && /[0-7]/.test(ch)
}

function isBinDigit(ch) {
  return ch === '0' || ch === '1'
}

function isIdentStart(ch) {
  return isLetter(ch) || ch === '_'
}

function isIdentPart(ch) {
  return isLetter(ch) || isDigit(ch) || ch === '_'
}

export class LexError extends Error {
  constructor(line, column, reason) {
    super(`${line}:${column}: ${reason}`)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

class Scanner {
  constructor(source) {
    // Split by code point so that surrogate pairs count as one character,
    // matching the "every other code point" rule in the spec.
    this.chars = Array.from(source)
    this.pos = 0
    this.line = 1
    this.column = 1
  }

  atEnd(offset = 0) {
    return this.pos + offset >= this.chars.length
  }

  peek(offset = 0) {
    return this.chars[this.pos + offset]
  }

  here() {
    return { line: this.line, column: this.column }
  }

  advance() {
    const ch = this.chars[this.pos]
    this.pos++
    if (ch === '\n') {
      this.line++
      this.column = 1
    } else if (ch === '\t') {
      this.column = Math.floor((this.column - 1) / TAB_WIDTH) * TAB_WIDTH + TAB_WIDTH + 1
    } else {
      this.column++
    }
    return ch
  }

  fail(pos, reason) {
    throw new LexError(pos.line, pos.column, reason)
