 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { normalizeUri, resolveUri, PercentEncodingError, NoSchemeError } from './uri.js'

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch (err) {
    if (err.code === 'EAGAIN' || err.code === 'ENXIO') return ''
    throw err
  }
}

function splitRecords(input) {
  if (input === '') return []
  const trimmed = input.endsWith('\n') ? input.slice(0, -1) : input
  return trimmed.split('\n')
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
    fail('usage: cli.js normalize|resolve')
  }

  const input = readStdin()
  const records = splitRecords(input)
  const results = []

  for (let i = 0; i < records.length; i++) {
    const lineNumber = i + 1
    const record = records[i]
    try {
      if (mode === 'normalize') {
        results.push(normalizeUri(record))
      } else {
        const spaceIdx = record.indexOf(' ')
        if (spaceIdx === -1) {
          fail(`line ${lineNumber}: expected a base and a reference`)
        }
        const base = record.slice(0, spaceIdx)
        const ref = record.slice(spaceIdx + 1)
        results.push(resolveUri(base, ref))
      }
    } catch (err) {
      if (err instanceof NoSchemeError) {
        fail(`line ${lineNumber}: the base has no scheme`)
      } else if (err instanceof PercentEncodingError) {
        fail(`line ${lineNumber}: ${err.message}`)
      }
      throw err
    }
  }

  if (results.length > 0) {
    process.stdout.write(results.join('\n') + '\n')
  }
  process.exit(0)
}

main()
"}

