/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */
import { CliError } from './errors.js'
import { parseElection } from './parse.js'
import { runElection } from './election.js'

function readStdin() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
    fail('usage: cli.js rounds|tally')
  }

  const input = readStdinSync()

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof CliError) {
      fail(err.line === null ? err.message : `line ${err.line}: ${err.message}`)
    }
    throw err
  }

  const { rounds, winner } = runElection(election.candidates, election.ballots)

  const out = []
  if (mode === 'rounds') {
    rounds.forEach((round, index) => {
      const parts = round.counts.map(([name, count]) => `${name}=${count}`)
      out.push(`round ${index + 1}: ${parts.join(' ')} exhausted=${round.exhausted}`)
      if (round.eliminated !== null) out.push(`eliminated ${round.eliminated}`)
    })
  } else {
    out.push(`rounds ${rounds.length}`)
  }
  out.push(winner === null ? 'no winner' : `winner ${winner}`)

  process.stdout.write(out.join('\n') + '\n')
}

function readStdinSync() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

main()
"}

