/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { Evaluator } from './evaluator.js'
import { parseSheet, SheetError } from './sheet.js'
import { formatValue } from './values.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (e) {
      if (e.code === 'EAGAIN') continue
      if (e.code === 'EOF') break
      throw e
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
    fail('usage: cli.js values|deps')
  }
  const mode = args[0]

  const input = readStdin()

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(e.message)
    }
    throw e
  }

  const evaluator = new Evaluator(cells)
  const keys = evaluator.sortedKeys()
  const lines = []

  if (mode === 'values') {
    for (const key of keys) {
      const value = evaluator.valueFor(key)
      lines.push(`${key}=${formatValue(value)}`)
    }
  } else {
    for (const key of keys) {
      const deps = evaluator.depsFor(key)
      const depText = deps.map((d) => ` ${d.key}`).join('')
      lines.push(`${key}:${depText}`)
    }
  }

  process.stdout.write(lines.length > 0 ? lines.join('\n') + '\n' : '')
  process.exit(0)
}

main()
"}

