 * Renders a parsed document as canonical JSON or as a `keys` listing.
 */

import { TomlTable, TomlArray, TomlAoT } from './model.js'

/** Compares strings by ascending Unicode code point, not UTF-16 code unit. */
export function compareCodePoint(a, b) {
  const ai = Array.from(a)
  const bi = Array.from(b)
  const len = Math.min(ai.length, bi.length)
  for (let k = 0; k < len; k++) {
    const pa = ai[k].codePointAt(0)
    const pb = bi[k].codePointAt(0)
    if (pa !== pb) return pa - pb
  }
  return ai.length - bi.length
}

function typeOf(node) {
  if (node instanceof TomlTable) return 'table'
  if (node instanceof TomlArray || node instanceof TomlAoT) return 'array'
  return node.t
}

function jsonScalar(node) {
  switch (node.t) {
    case 'string': return JSON.stringify(node.v)
    case 'boolean': return node.v ? 'true' : 'false'
    case 'integer': return node.v.toString()
    case 'float': return JSON.stringify(node.v)
    default: throw new Error(`unreachable scalar type ${node.t}`)
  }
}

function jsonValue(node, indent) {
  if (node instanceof TomlTable) return jsonTable(node, indent)
  if (node instanceof TomlArray || node instanceof TomlAoT) return jsonArray(node.items, indent)
  return jsonScalar(node)
}

function jsonTable(tbl, indent) {
  const keys = Array.from(tbl.entries.keys()).sort(compareCodePoint)
  if (keys.length === 0) return '{}'
  const pad = '  '.repeat(indent + 1)
  const closePad = '  '.repeat(indent)
  const parts = keys.map(k => `${pad}${JSON.stringify(k)}: ${jsonValue(tbl.entries.get(k), indent + 1)}`)
  return `{\n${parts.join(',\n')}\n${closePad}}`
}

function jsonArray(items, indent) {
  if (items.length === 0) return '[]'
  const pad = '  '.repeat(indent + 1)
  const closePad = '  '.repeat(indent)
  const parts = items.map(it => `${pad}${jsonValue(it, indent + 1)}`)
  return `[\n${parts.join(',\n')}\n${closePad}]`
}

export function toJSON(root) {
  return `${jsonValue(root, 0)}\n`
}

function emitKeys(node, path, out) {
  if (node instanceof TomlTable) {
    const keys = Array.from(node.entries.keys()).sort(compareCodePoint)
    for (const k of keys) {
      const child = node.entries.get(k)
      const childPath = path === '' ? k : `${path}.${k}`
      out.push(`${childPath} ${typeOf(child)}`)
      emitKeys(child, childPath, out)
    }
  } else if (node instanceof TomlArray || node instanceof TomlAoT) {
    node.items.forEach((item, i) => {
      const childPath = `${path}[${i}]`
      out.push(`${childPath} ${typeOf(item)}`)
      emitKeys(item, childPath, out)
    })
  }
}

export function toKeys(root) {
  const out = []
  emitKeys(root, '', out)
  return out.length === 0 ? '' : `${out.join('\n')}\n`
}
"}

