 * The two policy kinds a limiter file can declare, each keeping one
 * independent state per key. States are plain objects created lazily the
 * first time a key reaches the policy.
 */

const NAME_PATTERN = /^[A-Za-z0-9_./:-]+$/

export function isValidName(text) {
  return NAME_PATTERN.test(text)
}

/**
 * A token bucket. Token counts are tracked as an exact fraction with a
 * fixed denominator of `per`, stored as a BigInt numerator, so partial
 * refills never lose precision to floating point rounding.
 */
export class Bucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.states = new Map()
  }

  stateFor(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { numerator: BigInt(this.capacity) * BigInt(this.per), lastTick: null }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.stateFor(key)
    if (state.lastTick === null) {
      state.lastTick = tick
      return
    }
    const elapsed = tick - state.lastTick
    if (elapsed > 0) {
      const cap = BigInt(this.capacity) * BigInt(this.per)
      state.numerator += BigInt(this.refill) * BigInt(elapsed)
      if (state.numerator > cap) state.numerator = cap
      state.lastTick = tick
    }
  }

  allow(key) {
    return this.stateFor(key).numerator >= BigInt(this.per)
  }

  record(key) {
    this.stateFor(key).numerator -= BigInt(this.per)
  }
}

/** A sliding window, remembering the ticks of the requests it recorded per key. */
export class Window {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  stateFor(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { ticks: [] }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.stateFor(key)
    const threshold = tick - this.span
    let drop = 0
    while (drop < state.ticks.length && state.ticks[drop] <= threshold) drop += 1
    if (drop > 0) state.ticks.splice(0, drop)
  }

  allow(key) {
    return this.stateFor(key).ticks.length < this.limit
  }

  record(key, tick) {
    this.stateFor(key).ticks.push(tick)
  }
}
"}

