{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-sEfWRM/src/parser.js","content":"/**
 * Parses a limiter file's text into declared policies, routes and events,
 * validating every directive as the specification requires and raising a
 * `LimiterError` naming the first offending line.
 */
import { LimiterError } from './errors.js'
import { isValidName } from './policies.js'

const INTEGER_PATTERN = /^(0|[1-9][0-9]*)$/

function parseCount(line, field, text, least) {
  if (!INTEGER_PATTERN.test(text) || Number(text) < least) {
    throw new LimiterError(line, `${field} must be an integer of at least ${least}`)
  }
  return Number(text)
}

/**
 * @param {string} text the raw limiter file
 * @returns {{policies: Map<string, object>, routes: Array<{prefix: string, policyNames: string[]}>, events: Array<{tick: number, key: string}>}}
 */
export function parseLimiterFile(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const policies = new Map()
  const routes = []
  const routePrefixes = new Set()
  const events = []
  let eventsStarted = false
  let lastTick = null

  for (let index = 0; index < rawLines.length; index += 1) {
    const lineNumber = index + 1
    const trimmed = rawLines[index].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (eventsStarted) {
        throw new LimiterError(lineNumber, 'declarations must come before the first event')
      }
    }

    if (directive === 'bucket') {
      if (tokens.length !== 5) {
        throw new LimiterError(lineNumber, 'expected bucket <name> <capacity> <refill> <per>')
      }
      const [, name, capacityText, refillText, perText] = tokens
      if (!isValidName(name)) throw new LimiterError(lineNumber, `invalid policy name ${name}`)
      if (policies.has(name)) throw new LimiterError(lineNumber, `policy ${name} is declared twice`)
      const capacity = parseCount(lineNumber, 'capacity', capacityText, 1)
      const refill = parseCount(lineNumber, 'refill', refillText, 0)
      const per = parseCount(lineNumber, 'per', perText, 1)
      policies.set(name, { type: 'bucket', capacity, refill, per })
    } else if (directive === 'window') {
      if (tokens.length !== 4) {
        throw new LimiterError(lineNumber, 'expected window <name> <limit> <span>')
      }
      const [, name, limitText, spanText] = tokens
      if (!isValidName(name)) throw new LimiterError(lineNumber, `invalid policy name ${name}`)
      if (policies.has(name)) throw new LimiterError(lineNumber, `policy ${name} is declared twice`)
      const limit = parseCount(lineNumber, 'limit', limitText, 0)
      const span = parseCount(lineNumber, 'span', spanText, 1)
      policies.set(name, { type: 'window', limit, span })
    } else if (directive === 'route') {
      if (tokens.length < 3) {
        throw new LimiterError(lineNumber, 'expected route <prefix> <policy>...')
      }
      const prefix = tokens[1]
      if (!isValidName(prefix)) throw new LimiterError(lineNumber, `invalid route prefix ${prefix}`)
      if (routePrefixes.has(prefix)) throw new LimiterError(lineNumber, `prefix ${prefix} is routed twice`)
      const policyNames = tokens.slice(2)
      for (const policyName of policyNames) {
        if (!policies.has(policyName)) throw new LimiterError(lineNumber, `unknown policy ${policyName}`)
      }
      routePrefixes.add(prefix)
      routes.push({ prefix, policyNames })
    } else if (directive === 'event') {
      if (tokens.length !== 3) {
        throw new LimiterError(lineNumber, 'expected event <tick> <key>')
      }
      const [, tickText, key] = tokens
      const tick = parseCount(lineNumber, 'tick', tickText, 0)
      if (lastTick !== null && tick < lastTick) {
        throw new LimiterError(lineNumber, `tick ${tick} is before tick ${lastTick}`)
      }
      if (!isValidName(key)) throw new LimiterError(lineNumber, `invalid key ${key}`)
      eventsStarted = true
      lastTick = tick
      events.push({ tick, key })
    } else {
      throw new LimiterError(lineNumber, `unknown directive ${directive}`)
    }
  }

  return { policies, routes, events }
}
"}

