 * Replays a parsed limiter file's events against its policies, in order,
 * producing one verdict per event.
 */
import { Bucket, Window } from './policies.js'

function buildPolicies(policyDefs) {
  const policies = new Map()
  for (const [name, def] of policyDefs) {
    if (def.type === 'bucket') {
      policies.set(name, new Bucket(def.capacity, def.refill, def.per))
    } else {
      policies.set(name, new Window(def.limit, def.span))
    }
  }
  return policies
}

/** Finds the route whose prefix is the longest match for `key`, or null. */
function matchRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix) && (best === null || route.prefix.length > best.prefix.length)) {
      best = route
    }
  }
  return best
}

/**
 * @returns {Array<{tick: number, key: string, allow: boolean, deniedBy: string|null}>}
 */
export function simulate({ policies: policyDefs, routes, events }) {
  const policies = buildPolicies(policyDefs)
  const verdicts = []

  for (const { tick, key } of events) {
    const route = matchRoute(routes, key)
    if (route === null) {
      verdicts.push({ tick, key, allow: true, deniedBy: null })
      continue
    }

    const routePolicies = route.policyNames.map((name) => policies.get(name))
    for (const policy of routePolicies) policy.advance(key, tick)

    let deniedBy = null
    for (let index = 0; index < routePolicies.length; index += 1) {
      if (!routePolicies[index].allow(key)) {
        deniedBy = route.policyNames[index]
        break
      }
    }

    if (deniedBy === null) {
      for (const policy of routePolicies) policy.record(key, tick)
      verdicts.push({ tick, key, allow: true, deniedBy: null })
    } else {
      verdicts.push({ tick, key, allow: false, deniedBy })
    }
  }

  return verdicts
}
"}

