{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-sEfWRM/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { LimiterError } from './errors.js'
import { parseLimiterFile } from './parser.js'
import { simulate } from './simulate.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (error) {
      if (error.code === 'EAGAIN') continue
      if (error.code === 'EOF') break
      throw error
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function formatReplay(verdicts) {
  const lines = []
  for (const verdict of verdicts) {
    if (verdict.allow) {
      lines.push(`${verdict.tick} ${verdict.key} allow`)
    } else {
      lines.push(`${verdict.tick} ${verdict.key} deny ${verdict.deniedBy}`)
    }
  }
  return lines.join('')
}

function formatSummary(verdicts) {
  const totals = new Map()
  let totalAllowed = 0
  let totalDenied = 0
  for (const verdict of verdicts) {
    let entry = totals.get(verdict.key)
    if (entry === undefined) {
      entry = { allowed: 0, denied: 0 }
      totals.set(verdict.key, entry)
    }
    if (verdict.allow) {
      entry.allowed += 1
      totalAllowed += 1
    } else {
      entry.denied += 1
      totalDenied += 1
    }
  }

  const lines = []
  const keys = [...totals.keys()].sort()
  for (const key of keys) {
    const entry = totals.get(key)
    lines.push(`${key} allowed=${entry.allowed} denied=${entry.denied}\n`)
  }
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}\n`)
  return lines.join('')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  const text = readStdin()

  let parsed
  try {
    parsed = parseLimiterFile(text)
  } catch (error) {
    if (error instanceof LimiterError) {
      process.stderr.write(`error: line ${error.line}: ${error.reason}\n`)
      process.exit(2)
    }
    throw error
  }

  const verdicts = simulate(parsed)
  const output = mode === 'replay' ? formatReplayLines(verdicts) : formatSummary(verdicts)
  process.stdout.write(output)
  process.exit(0)
}

function formatReplayLines(verdicts) {
  let output = ''
  for (const verdict of verdicts) {
    if (verdict.allow) {
      output += `${verdict.tick} ${verdict.key} allow\n`
    } else {
      output += `${verdict.tick} ${verdict.key} deny ${verdict.deniedBy}\n`
    }
  }
  return output
}

main()
"}

