{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-y5hzLx/src/policies.js","content":"/**
 * The two policy kinds a limiter file can declare. Both keep one
 * independent state per key and are advanced to an event's tick before
 * being asked whether they allow it.
 */

/**
 * A token bucket. Tokens are tracked in units of 1/per so that partial
 * refill periods accumulate exactly, with no rounding.
 */
export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.fullUnits = capacity * per
    this.units = new Map()
    this.lastTick = new Map()
  }

  advance(key, tick) {
    if (!this.units.has(key)) {
      this.units.set(key, this.fullUnits)
      this.lastTick.set(key, tick)
      return
    }
    const last = this.lastTick.get(key)
    const elapsed = tick - last
    if (elapsed > 0n) {
      let units = this.units.get(key) + this.refill * elapsed
      if (units > this.fullUnits) units = this.fullUnits
      this.units.set(key, units)
      this.lastTick.set(key, tick)
    }
  }

  allows(key) {
    return this.units.get(key) >= this.per
  }

  record(key) {
    this.units.set(key, this.units.get(key) - this.per)
  }
}

/** A sliding window that remembers the ticks it recorded for each key. */
export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.remembered = new Map()
  }

  advance(key, tick) {
    let ticks = this.remembered.get(key)
    if (!ticks) {
      ticks = []
      this.remembered.set(key, ticks)
    }
    const cutoff = tick - this.span
    let start = 0
    while (start < ticks.length && ticks[start] <= cutoff) start++
    if (start > 0) ticks.splice(0, start)
  }

  allows(key) {
    return BigInt(this.remembered.get(key).length) < this.limit
  }

  record(key, tick) {
    this.remembered.get(key).push(tick)
  }
}
"}

