 * Parses a limiter file's text into declared policies, routes and events.
 * Throws a ParseError naming the offending line on any violation of the
 * grammar or the constraints layered on top of it.
 */
import { TokenBucket, SlidingWindow } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_./:-]+$/
const UINT_RE = /^(0|[1-9][0-9]*)$/

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

function requireUint(token, field, least, line) {
  if (!UINT_RE.test(token) || BigInt(token) < least) {
    throw new ParseError(line, `${field} must be an integer of at least ${least}`)
  }
  return BigInt(token)
}

/**
 * @param {string} text the raw limiter file
 * @returns {{ policies: Map<string, object>, routes: { prefix: string, policies: object[] }[], events: { line: number, tick: bigint, key: string }[] }}
 */
export function parseFile(text) {
  let lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routePrefixes = new Map()
  const routes = []
  const events = []
  let eventSeen = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'bucket') {
      if (tokens.length !== 5) {
        throw new ParseError(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      }
      const [, name, capacityTok, refillTok, perTok] = tokens
      if (!NAME_RE.test(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
      if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
      if (eventSeen) throw new ParseError(lineNo, 'declarations must come before the first event')
      const capacity = requireUint(capacityTok, 'capacity', 1n, lineNo)
      const refill = requireUint(refillTok, 'refill', 0n, lineNo)
      const per = requireUint(perTok, 'per', 1n, lineNo)
      policies.set(name, { name, policy: new TokenBucket(capacity, refill, per) })
    } else if (word === 'window') {
      if (tokens.length !== 4) {
        throw new ParseError(lineNo, 'expected window <name> <limit> <span>')
      }
      const [, name, limitTok, spanTok] = tokens
      if (!NAME_RE.test(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
      if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
      if (eventSeen) throw new ParseError(lineNo, 'declarations must come before the first event')
      const limit = requireUint(limitTok, 'limit', 0n, lineNo)
      const span = requireUint(spanTok, 'span', 1n, lineNo)
      policies.set(name, { name, policy: new SlidingWindow(limit, span) })
    } else if (word === 'route') {
      if (tokens.length < 3) {
        throw new ParseError(lineNo, 'expected route <prefix> <policy>...')
      }
      const prefix = tokens[1]
      if (!NAME_RE.test(prefix)) throw new ParseError(lineNo, `invalid route prefix ${prefix}`)
      if (routePrefixes.has(prefix)) throw new ParseError(lineNo, `prefix ${prefix} is routed twice`)
      const policyNames = tokens.slice(2)
      const resolved = []
      for (const pname of policyNames) {
        const entry = policies.get(pname)
        if (!entry) throw new ParseError(lineNo, `unknown policy ${pname}`)
        resolved.push(entry)
      }
      if (eventSeen) throw new ParseError(lineNo, 'declarations must come before the first event')
      const route = { prefix, policies: resolved }
      routePrefixes.set(prefix, route)
      routes.push(route)
    } else if (word === 'event') {
      if (tokens.length !== 3) {
        throw new ParseError(lineNo, 'expected event <tick> <key>')
      }
      const [, tickTok, key] = tokens
      if (!NAME_RE.test(key)) throw new ParseError(lineNo, `invalid key ${key}`)
      const tick = requireUint(tickTok, 'tick', 0n, lineNo)
      if (lastTick !== null && tick < lastTick) {
        throw new ParseError(lineNo, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      eventSeen = true
      events.push({ line: lineNo, tick, key })
    } else {
      throw new ParseError(lineNo, `unknown directive ${word}`)
    }
  }

  return { policies, routes, events }
}
"}

