 * Resolves each event to its route and drives the policies on that route,
 * producing one verdict per event and the running per-key summary.
 */

/** Finds the route whose prefix matches the key and is longest, if any. */
function findRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix)) {
      if (best === null || route.prefix.length > best.prefix.length) best = route
    }
  }
  return best
}

/**
 * @returns {{ verdicts: { line: number, tick: bigint, key: string, allowed: boolean, deniedBy: string|null }[], summary: Map<string, { allowed: number, denied: number }> }}
 */
export function simulate({ routes, events }) {
  const verdicts = []
  const summary = new Map()

  for (const event of events) {
    const { tick, key } = event
    const route = findRoute(routes, key)

    let allowed = true
    let deniedBy = null

    if (route) {
      for (const entry of route.policies) entry.policy.advance(key, tick)
      for (const entry of route.policies) {
        if (!entry.policy.allows(key)) {
          allowed = false
          deniedBy = entry.name
          break
        }
      }
      if (allowed) {
        for (const entry of route.policies) entry.policy.record(key, tick)
      }
    }

    verdicts.push({ line: event.line, tick, key, allowed, deniedBy })

    let counts = summary.get(key)
    if (!counts) {
      counts = { allowed: 0, denied: 0 }
      summary.set(key, counts)
    }
    if (allowed) counts.allowed++
    else counts.denied++
  }

  return { verdicts, summary }
}
"}

