{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-y5hzLx/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { parseFile, ParseError } from './parse.js'
import { simulate } from './simulate.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

async function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
    fail('usage: cli.js replay|summary')
    return
  }

  const chunks = []
  for await (const chunk of process.stdin) chunks.push(chunk)
  const text = chunks.join('')

  let parsed
  try {
    parsed = parseFile(text)
  } catch (err) {
    if (err instanceof ParseError) {
      fail(err.message)
      return
    }
    throw err
  }

  const { verdicts, summary } = simulate(parsed)

  const out = []
  if (mode === 'replay') {
    for (const v of verdicts) {
      out.push(v.allowed ? `${v.tick} ${v.key} allow` : `${v.tick} ${v.key} deny ${v.deniedBy}`)
    }
  } else {
    const keys = [...summary.keys()].sort()
    let totalAllowed = 0
    let totalDenied = 0
    for (const key of keys) {
      const counts = summary.get(key)
      out.push(`${key} allowed=${counts.allowed} denied=${counts.denied}`)
      totalAllowed += counts.allowed
      totalDenied += counts.denied
    }
    out.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  }

  process.stdout.write(out.length ? out.join('\n') + '\n' : '')
  process.exit(0)
}

main()
"}

